/// <summary>
/// 频道列表项视图模型：包裹不可变的 <see cref="LiveChannel"/> 记录，
/// 额外承载可变的测速状态（徽标颜色、延迟/速率标签），供 ListBox 的 ItemTemplate 绑定。
/// </summary>
public sealed class LiveChannelViewModel : INotifyPropertyChanged
{
    private static readonly Brush UnknownBrush = Frozen("#5A5F66");
    private static readonly Brush GoodBrush = Frozen("#00A862");
    private static readonly Brush FairBrush = Frozen("#E6A700");
    private static readonly Brush BadBrush = Frozen("#E5484D");

    private ChannelHealthResult _health = new(ChannelHealth.Unknown, 0, string.Empty);
    private bool _isProbing;

    public LiveChannelViewModel(string key, LiveChannel channel)
    {
        Key = key;
        Channel = channel;
    }

    /// <summary>批量探测时用于回填结果的稳定键（与频道在列表中的位置一一对应）。</summary>
    public string Key { get; }

    public LiveChannel Channel { get; }

    public string Name => Channel.Name;

    public string Url => Channel.Url;

    public ChannelHealthResult Health
    {
        get => _health;
        set
        {
            _health = value;
            IsProbing = false;
            OnPropertyChanged(nameof(Health));
            OnPropertyChanged(nameof(BadgeBrush));
            OnPropertyChanged(nameof(MetricLabel));
            OnPropertyChanged(nameof(DetailTooltip));
            OnPropertyChanged(nameof(MetricTooltip));
        }
    }

    /// <summary>该频道正在探测中（用于显示等待态）。</summary>
    public bool IsProbing
    {
        get => _isProbing;
        set
        {
            if (_isProbing == value)
            {
                return;
            }

            _isProbing = value;
            OnPropertyChanged(nameof(IsProbing));
            OnPropertyChanged(nameof(BadgeBrush));
            OnPropertyChanged(nameof(MetricLabel));
            OnPropertyChanged(nameof(MetricTooltip));
        }
    }

    public Brush BadgeBrush => _isProbing
        ? UnknownBrush
        : _health.Health switch
        {
            ChannelHealth.Good => GoodBrush,
            ChannelHealth.Fair => FairBrush,
            ChannelHealth.Bad => BadBrush,
            _ => UnknownBrush,
        };

    public string? DetailTooltip => string.IsNullOrEmpty(_health.Detail) ? Name : $"{Name} · {_health.Detail}";

    public string MetricLabel => _isProbing ? "测速中" : ChannelHealthDisplay.MetricsLabelOf(_health);

    public string MetricTooltip => $"{Name} · {ChannelHealthDisplay.MetricsLabelOf(_health)}";

    public event PropertyChangedEventHandler? PropertyChanged;

    private void OnPropertyChanged([CallerMemberName] string? name = null) =>
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));

    private static Brush Frozen(string hex)
    {
        var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex));
        brush.Freeze();
        return brush;
    }
}

using System.Windows;
using System.Windows.Input;
using System.Windows.Media.Animation;
using System.Windows.Threading;

namespace OrionTV.Desktop.App.Views;

/// <summary>
/// 播放器 OSD 自动隐藏：鼠标移动时显示控制层并重置计时，静止数秒后淡出并隐藏光标；
/// 通过 <see cref="Pin"/> 在侧栏/频道列表展开或鼠标悬停控制栏时锁定显示。
/// </summary>
public sealed class OsdController
{
    private static readonly Duration FadeDuration = new(TimeSpan.FromMilliseconds(180));

    private readonly FrameworkElement _host;
    private readonly UIElement[] _layers;
    private readonly DispatcherTimer _timer;
    private bool _pinned;
    private bool _visible = true;

    public OsdController(FrameworkElement host, params UIElement[] layers)
    {
        _host = host;
        _layers = layers;
        _timer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(3) };
        _timer.Tick += (_, _) =>
        {
            _timer.Stop();
            if (!_pinned)
            {
                Hide();
            }
        };

        _host.MouseMove += (_, _) => Show();
        _host.MouseLeave += (_, _) =>
        {
            if (!_pinned)
            {
                Hide();
            }
        };
    }

    /// <summary>锁定/解锁显示（如侧栏打开、鼠标悬停控制栏时锁定）。</summary>
    public void Pin(bool pinned)
    {
        _pinned = pinned;
        if (pinned)
        {
            Show();
        }
        else
        {
            RestartTimer();
        }
    }

    public void Show()
    {
        if (!_visible)
        {
            _visible = true;
            foreach (var layer in _layers)
            {
                Fade(layer, 1);
            }
        }

        _host.Cursor = Cursors.Arrow;
        RestartTimer();
    }

    public void Hide()
    {
        if (!_visible)
        {
            return;
        }

        _visible = false;
        foreach (var layer in _layers)
        {
            Fade(layer, 0);
        }

        _host.Cursor = Cursors.None;
    }

    private void RestartTimer()
    {
        _timer.Stop();
        if (!_pinned)
        {
            _timer.Start();
        }
    }

    private static void Fade(UIElement layer, double to)
    {
        layer.IsHitTestVisible = to > 0;
        layer.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(to, FadeDuration));
    }
}

using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Input;
using System.Windows.Interop;

namespace OrionTV.Desktop.App.Views;

/// <summary>
/// Captures player shortcuts even when keyboard focus belongs to an embedded native video HWND
/// (LibVLC or the out-of-process mpv child window).
/// </summary>
internal sealed class PlayerKeyboardHook : IDisposable
{
    private const int WhKeyboardLl = 13;
    private const int WmKeyDown = 0x0100;
    private const int GaRoot = 2;
    private const int GaRootOwner = 3;
    private const int VkShift = 0x10;
    private const int VkControl = 0x11;
    private const int VkMenu = 0x12;
    private const int VkLWin = 0x5B;
    private const int VkRWin = 0x5C;

    private readonly IntPtr _ownerHandle;
    private readonly Func<Key, ModifierKeys, bool> _handler;
    private readonly HookProc _hookProc;
    private IntPtr _hookHandle;

    private PlayerKeyboardHook(IntPtr ownerHandle, Func<Key, ModifierKeys, bool> handler)
    {
        _ownerHandle = ownerHandle;
        _handler = handler;
        _hookProc = HookCallback;
        _hookHandle = SetWindowsHookEx(WhKeyboardLl, _hookProc, GetModuleHandle(null), 0);
    }

    internal static PlayerKeyboardHook? TryCreate(
        Window owner,
        Func<Key, ModifierKeys, bool> handler)
    {
        var ownerHandle = new WindowInteropHelper(owner).EnsureHandle();
        if (ownerHandle == IntPtr.Zero)
        {
            return null;
        }

        var hook = new PlayerKeyboardHook(ownerHandle, handler);
        if (hook._hookHandle != IntPtr.Zero)
        {
            return hook;
        }

        hook.Dispose();
        return null;
    }

    private IntPtr HookCallback(int code, IntPtr message, IntPtr data)
    {
        if (code >= 0
            && message.ToInt32() == WmKeyDown
            && IsOwnerForeground())
        {
            var keyboard = Marshal.PtrToStructure<KbdLlHookStruct>(data);
            var key = KeyInterop.KeyFromVirtualKey((int)keyboard.VirtualKey);
            try
            {
                if (_handler(key, ReadModifiers()))
                {
                    return new IntPtr(1);
                }
            }
            catch
            {
                // A shortcut failure must never break the process-wide keyboard hook chain.
            }
        }

        return CallNextHookEx(_hookHandle, code, message, data);
    }

    private bool IsOwnerForeground()
    {
        var foreground = GetForegroundWindow();
        if (foreground == IntPtr.Zero)
        {
            return false;
        }

        return GetAncestor(foreground, GaRoot) == _ownerHandle
            || GetAncestor(foreground, GaRootOwner) == _ownerHandle;
    }

    private static ModifierKeys ReadModifiers()
    {
        var modifiers = ModifierKeys.None;
        if (IsKeyDown(VkShift)) modifiers |= ModifierKeys.Shift;
        if (IsKeyDown(VkControl)) modifiers |= ModifierKeys.Control;
        if (IsKeyDown(VkMenu)) modifiers |= ModifierKeys.Alt;
        if (IsKeyDown(VkLWin) || IsKeyDown(VkRWin)) modifiers |= ModifierKeys.Windows;
        return modifiers;
    }

    private static bool IsKeyDown(int virtualKey) => (GetAsyncKeyState(virtualKey) & 0x8000) != 0;

    public void Dispose()
    {
        var handle = Interlocked.Exchange(ref _hookHandle, IntPtr.Zero);
        if (handle != IntPtr.Zero)
        {
            _ = UnhookWindowsHookEx(handle);
        }
    }

    [StructLayout(LayoutKind.Sequential)]
    private readonly struct KbdLlHookStruct
    {
        internal readonly uint VirtualKey;
        internal readonly uint ScanCode;
        internal readonly uint Flags;
        internal readonly uint Time;
        internal readonly UIntPtr ExtraInfo;
    }

    private delegate IntPtr HookProc(int code, IntPtr message, IntPtr data);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern IntPtr SetWindowsHookEx(
        int hookId,
        HookProc hookProc,
        IntPtr moduleHandle,
        uint threadId);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool UnhookWindowsHookEx(IntPtr hookHandle);

    [DllImport("user32.dll")]
    private static extern IntPtr CallNextHookEx(
        IntPtr hookHandle,
        int code,
        IntPtr message,
        IntPtr data);

    [DllImport("user32.dll")]
    private static extern IntPtr GetForegroundWindow();

    [DllImport("user32.dll")]
    private static extern IntPtr GetAncestor(IntPtr window, int flags);

    [DllImport("user32.dll")]
    private static extern short GetAsyncKeyState(int virtualKey);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)]
    private static extern IntPtr GetModuleHandle(string? moduleName);
}

